{
  "title": "Một ngày thong thả quanh Đà Lạt",
  "summary": "Một ngày nhẹ nhàng quanh khu vực trung tâm, vừa đủ để thưởng thức hương vị địa phương và nhịp sống về đêm.",
  "stops": [
    {
      "poi_id": "p179",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa trưa đúng chất Đà Lạt, gọn nhẹ mà ấm bụng trước khi dạo phố."
    },
    {
      "poi_id": "p180",
      "kind": "activity",
      "must_do_id": null,
      "note": "Đồi cỏ hồng chiều nhẹ tênh, đứng đây nhìn mây trôi là thấy lòng chậm lại."
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tối ngồi xuống quen kiểu người địa phương, nem nướng cuốn rau thơm, ngon quá."
    },
    {
      "poi_id": "p144",
      "kind": "activity",
      "must_do_id": null,
      "note": "Sau bữa tối, ghé khu phức hợp này cho đúng chất cú đêm, không cần đi xa."
    }
  ]
}
```

